nearest-neighbor-search.pseudocode:
def knn(root, q, k):
    pq = MinHeap([(0, root)])  # (하한 거리, 노드·객체)
    result = []
    while pq and len(result) < k:
        d, e = pq.pop()  # 하한이 가장 작은 항목
        if e.is_object:
            result.append((d, e))  # 꺼낸 객체는 확정
        else:
            for c in e.children:
                # 노드는 MINDIST, 객체는 실제 거리
                pq.push((mindist(q, c), c))
    return result

negative-cycle.pseudocode:
def has_negative_cycle(V, edges, src):
    INF = float('inf')
    dist = [INF] * V
    dist[src] = 0
    for _ in range(V - 1):  # V-1회 반복 완화
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:  # V번째 반복: 검사만
        if dist[u] != INF and dist[u] + w < dist[v]:
            return True  # 여전히 갱신됨 → 음수 사이클
    return False  # src에서 도달 가능한 음수 사이클 없음

nested-loop-join.pseudocode:
def nested_loop_join(outer, inner_index, cond):
    for r in outer:  # 선행(드라이빙) 테이블 행
        if not cond(r):
            continue  # 선행 필터 먼저 적용
        # 후행: 조인 키 인덱스로 랜덤 액세스
        for s in inner_index.lookup(r.key):
            yield r + s  # 즉시 반환 → 부분범위 처리
# 인덱스 없으면 inner 전체 스캔 반복 → O(N×M)

net-present-value.pseudocode:
def npv(rate, cashflows, initial):
    pv = 0
    for t, cf in enumerate(cashflows, start=1):
        pv += cf / (1 + rate) ** t  # 미래 현금흐름 할인
    return pv - initial

def irr(cashflows, initial, lo=-0.99, hi=1.0, eps=1e-6):
    # NPV(r) = 0인 r을 이분 탐색 (일반형 현금흐름 가정)
    while hi - lo > eps:
        mid = (lo + hi) / 2
        if npv(mid, cashflows, initial) > 0:
            lo = mid  # 아직 양수 → 할인율 상향
        else:
            hi = mid
    return (lo + hi) / 2

